drop extension if exists "pg_net";

create extension if not exists "pg_trgm" with schema "public";


  create table "public"."book_ratings" (
    "id" bigint generated by default as identity not null,
    "user_id" uuid not null,
    "media_id" bigint not null,
    "prose" integer not null,
    "plot" integer not null,
    "characters" integer not null,
    "originality" integer not null,
    "pacing" integer not null,
    "resonance" integer not null,
    "review" text,
    "created_at" timestamp with time zone not null default now()
      );


alter table "public"."book_ratings" enable row level security;


  create table "public"."books" (
    "id" smallint generated by default as identity not null,
    "title" text not null,
    "author" text,
    "year" integer,
    "genre" text,
    "synopsis" text,
    "cover_url" text,
    "source_key" text,
    "created_at" timestamp with time zone not null default now(),
    "item_url" text,
    "external_id" text
      );


alter table "public"."books" enable row level security;


  create table "public"."chat_logs" (
    "id" bigint generated by default as identity not null,
    "user_id" uuid not null,
    "query" text not null,
    "intent" text,
    "response_length" integer,
    "sources_count" integer,
    "latency_ms" integer,
    "created_at" timestamp with time zone not null default now()
      );


alter table "public"."chat_logs" enable row level security;


  create table "public"."media_list_collaborators" (
    "id" bigint generated by default as identity not null,
    "list_id" bigint not null,
    "user_id" uuid not null,
    "invited_by_user_id" uuid not null,
    "added_at" timestamp with time zone not null default now()
      );


alter table "public"."media_list_collaborators" enable row level security;


  create table "public"."media_list_items" (
    "id" bigint generated by default as identity not null,
    "list_id" bigint not null,
    "media_type" text not null,
    "media_id" bigint not null,
    "position" integer not null default 0,
    "added_at" timestamp with time zone not null default now()
      );


alter table "public"."media_list_items" enable row level security;


  create table "public"."media_list_votes" (
    "id" bigint generated by default as identity not null,
    "list_item_id" bigint not null,
    "user_id" uuid not null,
    "value" integer not null,
    "created_at" timestamp with time zone not null default now(),
    "updated_at" timestamp with time zone not null default now()
      );


alter table "public"."media_list_votes" enable row level security;


  create table "public"."media_lists" (
    "id" bigint generated by default as identity not null,
    "user_id" uuid not null,
    "name" text not null,
    "share_code" text not null,
    "is_public" boolean not null default false,
    "created_at" timestamp with time zone not null default now(),
    "updated_at" timestamp with time zone not null default now()
      );


alter table "public"."media_lists" enable row level security;


  create table "public"."media_requests" (
    "id" bigint generated by default as identity not null,
    "user_id" uuid not null,
    "title" text not null,
    "media_type" text not null,
    "year" integer,
    "reason" text,
    "status" text not null default 'pending'::text,
    "admin_note" text,
    "created_at" timestamp with time zone not null default now(),
    "updated_at" timestamp with time zone not null default now()
      );


alter table "public"."media_requests" enable row level security;


  create table "public"."movie_ratings" (
    "id" bigint generated by default as identity not null,
    "user_id" uuid not null,
    "media_id" bigint not null,
    "acting" integer not null,
    "writing" integer not null,
    "originality" integer not null,
    "pacing" integer not null,
    "cinematography" integer not null,
    "review" text,
    "created_at" timestamp with time zone not null default now()
      );


alter table "public"."movie_ratings" enable row level security;


  create table "public"."movies" (
    "id" bigint generated by default as identity not null,
    "title" text not null,
    "year" integer,
    "genre" text,
    "director" text,
    "writers" text,
    "cast_members" text,
    "age_rating" text,
    "overview" text,
    "synopsis" text,
    "poster_url" text,
    "source_key" text,
    "created_at" timestamp with time zone not null default now(),
    "external_id" text
      );


alter table "public"."movies" enable row level security;


  create table "public"."profiles" (
    "id" uuid not null,
    "email" text not null,
    "username" text not null,
    "bio" text not null default ''::text,
    "avatar_url" text,
    "created_at" timestamp with time zone not null default now(),
    "updated_at" timestamp with time zone not null default now()
      );


alter table "public"."profiles" enable row level security;


  create table "public"."todos" (
    "id" bigint generated by default as identity not null,
    "name" text not null,
    "created_at" timestamp with time zone not null default now()
      );


alter table "public"."todos" enable row level security;


  create table "public"."tv_show_ratings" (
    "id" bigint generated by default as identity not null,
    "user_id" uuid not null,
    "media_id" bigint not null,
    "premise" integer not null,
    "originality" integer not null,
    "acting" integer not null,
    "cinematography" integer not null,
    "writing" integer not null,
    "pacing" integer not null,
    "resonance" integer not null,
    "review" text,
    "created_at" timestamp with time zone not null default now()
      );


alter table "public"."tv_show_ratings" enable row level security;


  create table "public"."tv_shows" (
    "id" bigint generated by default as identity not null,
    "title" text not null,
    "year" integer,
    "genre" text,
    "creator" text,
    "writers" text,
    "cast_members" text,
    "age_rating" text,
    "overview" text,
    "synopsis" text,
    "poster_url" text,
    "seasons" integer,
    "source_key" text,
    "created_at" timestamp with time zone not null default now(),
    "external_id" text
      );


alter table "public"."tv_shows" enable row level security;


  create table "public"."watchlist" (
    "id" bigint generated by default as identity not null,
    "user_id" uuid not null,
    "media_type" text not null,
    "media_id" bigint not null,
    "status" text not null default 'plan_to_watch'::text,
    "added_at" timestamp with time zone not null default now()
      );


alter table "public"."watchlist" enable row level security;

