alter table "public"."tv_show_ratings" add constraint "tv_show_ratings_user_id_media_id_key" UNIQUE using index "tv_show_ratings_user_id_media_id_key";

alter table "public"."tv_show_ratings" add constraint "tv_show_ratings_writing_check" CHECK (((writing >= 1) AND (writing <= 6))) not valid;

alter table "public"."tv_show_ratings" validate constraint "tv_show_ratings_writing_check";

alter table "public"."watchlist" add constraint "watchlist_media_type_check" CHECK ((media_type = ANY (ARRAY['movie'::text, 'tv_show'::text, 'book'::text]))) not valid;

alter table "public"."watchlist" validate constraint "watchlist_media_type_check";

alter table "public"."watchlist" add constraint "watchlist_status_check" CHECK ((status = ANY (ARRAY['plan_to_watch'::text, 'watching'::text, 'watched'::text, 'plan_to_read'::text, 'reading'::text, 'read'::text]))) not valid;

alter table "public"."watchlist" validate constraint "watchlist_status_check";

