set check_function_bodies = off;

create or replace view "public"."book_genres" as  SELECT DISTINCT TRIM(BOTH FROM split_genre.genre_value) AS genre
   FROM (public.books
     CROSS JOIN LATERAL regexp_split_to_table(COALESCE(books.genre, ''::text), ','::text) split_genre(genre_value))
  WHERE (TRIM(BOTH FROM split_genre.genre_value) <> ''::text);


CREATE OR REPLACE FUNCTION public.handle_auth_user_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into public.profiles (id, email, username, bio, avatar_url)
  values (
    new.id,
    new.email,
    coalesce(
      new.raw_user_meta_data ->> 'username',
      split_part(new.email, '@', 1),
      'media-fan'
    ),
    coalesce(new.raw_user_meta_data ->> 'bio', ''),
    nullif(new.raw_user_meta_data ->> 'avatar_url', '')
  )
  on conflict (id) do update
  set
    email = excluded.email,
    username = coalesce(public.profiles.username, excluded.username),
    bio = coalesce(public.profiles.bio, excluded.bio),
    avatar_url = coalesce(public.profiles.avatar_url, excluded.avatar_url);

  return new;
end;
$function$
;

create or replace view "public"."movie_genres" as  SELECT DISTINCT TRIM(BOTH FROM split_genre.genre_value) AS genre
   FROM (public.movies
     CROSS JOIN LATERAL regexp_split_to_table(COALESCE(movies.genre, ''::text), ','::text) split_genre(genre_value))
  WHERE (TRIM(BOTH FROM split_genre.genre_value) <> ''::text);


CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
;

create or replace view "public"."tv_show_genres" as  SELECT DISTINCT TRIM(BOTH FROM split_genre.genre_value) AS genre
   FROM (public.tv_shows
     CROSS JOIN LATERAL regexp_split_to_table(COALESCE(tv_shows.genre, ''::text), ','::text) split_genre(genre_value))
  WHERE (TRIM(BOTH FROM split_genre.genre_value) <> ''::text);


